#pragma once

#include "generated/FosFontIds.h"

class GfxRenderer;

namespace fos::ui {

// FOs UI fonts (Space Grotesk, Space Mono). Generated by tools/fonts/build_fos_fonts.py.
namespace font {
constexpr int SMALL = FOS_SMALL_FONT_ID;      // 9 pt: status bar, labels, chips
constexpr int BODY = FOS_BODY_FONT_ID;        // 11 pt: rows, body text
constexpr int TITLE = FOS_TITLE_FONT_ID;      // 15 pt bold: screen titles
constexpr int LARGE = FOS_DISPLAY_FONT_ID;  // 26 pt bold: keypad, big values
constexpr int JUMBO = FOS_HUGE_FONT_ID;        // 44 pt bold digits: clock, balance, timers
constexpr int MONO = FOS_MONO_FONT_ID;        // 8 pt monospace: terminal
}  // namespace font

// Adds the FOs fonts to the renderer. Call once after renderer.begin().
void registerFonts(GfxRenderer& renderer);

}  // namespace fos::ui
